    // unique tokens (hashes, IDs, base64, etc) can exceed this even when under
    // the character cap. In that case index the longest prefix of the text
    // that fits, while always fully indexing the title and previous titles.
    await queryInterface.sequelize.query(`
    CREATE OR REPLACE FUNCTION documents_search_trigger() RETURNS trigger AS $$
    declare
      header tsvector;
      body text := substring(coalesce(new.text, ''), 1, 1000000);
      lo integer := 0;
      hi integer;
      mid integer;
    begin
      header :=
        setweight(to_tsvector('english', coalesce(new.title, '')),'A') ||
        setweight(to_tsvector('english', coalesce(array_to_string(new."previousTitles", ' , '),'')),'C');

      begin
        new."searchVector" := header || setweight(to_tsvector('english', body), 'D');
        return new;
      exception when program_limit_exceeded then
        -- fall through to find the longest prefix of the text that fits.
      end;

      -- Binary search on the prefix length: a prefix of length lo is known to
      -- fit, a prefix of length hi is known to be too large.
      new."searchVector" := header;
      hi := length(body);
      while hi - lo > 1024 loop
        mid := (lo + hi) / 2;
        begin
          new."searchVector" := header || setweight(to_tsvector('english', substring(body, 1, mid)), 'D');
          lo := mid;
        exception when program_limit_exceeded then
          hi := mid;
        end;
      end loop;
      return new;
    end
    $$ LANGUAGE plpgsql;
